namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

public class Course
{
    public int Id { get; set; }
    public int DepartmentId { get; set; }
    public string DepartmentCode { get; set; } = string.Empty;
    public string CourseNumber { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments =
    [
        new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
        new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Pure and applied mathematics including statistics." },
        new() { Id = 3, Name = "English", Code = "ENG", Description = "Literature, writing, and language studies." },
        new() { Id = 4, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
        new() { Id = 5, Name = "History", Code = "HIST", Description = "Exploration of past events and civilizations." },
    ];

    private readonly List<Course> _courses =
    [
        new() { Id = 1, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "CS 101", Title = "Introduction to Programming", Description = "Fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published extensively on CS pedagogy.", IsFeatured = true },
        new() { Id = 2, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "CS 201", Title = "Data Structures & Algorithms", Description = "In-depth study of data structures (trees, graphs, hash tables) and algorithm design techniques (divide and conquer, dynamic programming).", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Martinez", InstructorBio = "Dr. Martinez specializes in algorithm optimization and competitive programming. He holds a PhD from MIT.", IsFeatured = true },
        new() { Id = 3, DepartmentId = 1, DepartmentCode = "CS", CourseNumber = "CS 350", Title = "Operating Systems", Description = "Process management, memory management, file systems, and concurrency. Includes hands-on kernel programming labs.", Credits = 4, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Lisa Park", InstructorBio = "Dr. Park contributed to the Linux kernel and brings real-world systems experience to the classroom." },
        new() { Id = 4, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Kim", InstructorBio = "Dr. Kim is an award-winning educator with a passion for making calculus accessible to all students.", IsFeatured = true },
        new() { Id = 5, DepartmentId = 2, DepartmentCode = "MATH", CourseNumber = "MATH 301", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications.", Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Maria Gonzalez", InstructorBio = "Dr. Gonzalez researches applications of linear algebra in machine learning and data science." },
        new() { Id = 6, DepartmentId = 3, DepartmentCode = "ENG", CourseNumber = "ENG 102", Title = "Composition & Rhetoric", Description = "Develop college-level writing skills through essays, research papers, and peer review workshops.", Credits = 3, Schedule = "Mon/Wed 11:00–12:15 PM", InstructorName = "Prof. David Thompson", InstructorBio = "Prof. Thompson is a published author and writing coach with expertise in academic and creative writing." },
        new() { Id = 7, DepartmentId = 3, DepartmentCode = "ENG", CourseNumber = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity and society.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Angela White", InstructorBio = "Dr. White specializes in 20th-century American fiction and has authored three books on the subject.", IsFeatured = true },
        new() { Id = 8, DepartmentId = 4, DepartmentCode = "PHYS", CourseNumber = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes weekly lab sessions with hands-on experiments.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:50 PM", InstructorName = "Dr. Alan Foster", InstructorBio = "Dr. Foster is an experimental physicist whose research focuses on condensed matter physics." },
        new() { Id = 9, DepartmentId = 4, DepartmentCode = "PHYS", CourseNumber = "PHYS 220", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM + Fri Lab 1:00–3:50 PM", InstructorName = "Dr. Nina Patel", InstructorBio = "Dr. Patel's research in photonics has been published in Nature and Physical Review Letters." },
        new() { Id = 10, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "HIST 101", Title = "World History to 1500", Description = "A global survey of human civilizations from prehistory through the late medieval period.", Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", InstructorName = "Dr. Michael Brown", InstructorBio = "Dr. Brown is a historian of the ancient world with fieldwork experience in the Mediterranean." },
        new() { Id = 11, DepartmentId = 5, DepartmentCode = "HIST", CourseNumber = "HIST 320", Title = "The American Civil War", Description = "Causes, conduct, and consequences of the Civil War and Reconstruction era.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. Patricia Hughes", InstructorBio = "Dr. Hughes is a Civil War historian and consultant for documentary films on the era.", IsFeatured = true },
    ];

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> SearchCourses(string? searchTerm, int? departmentId)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
        {
            query = query.Where(c => c.DepartmentId == departmentId.Value);
        }

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.CourseNumber.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request)
    {
        // In a real app this would persist to a database
        return !string.IsNullOrWhiteSpace(request.StudentName)
            && !string.IsNullOrWhiteSpace(request.StudentId)
            && request.CourseId > 0
            && _courses.Any(c => c.Id == request.CourseId);
    }
}

