@page "/courses"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Browse Courses</PageTitle>

<h1>Browse Courses</h1>

<form method="get" action="courses" class="row g-3 mb-4">
    <div class="col-md-6">
        <label for="search" class="form-label">Search</label>
        <input type="text" class="form-control" id="search" name="search" value="@Search"
               placeholder="Search by title, number, or instructor..." />
    </div>
    <div class="col-md-4">
        <label for="departmentId" class="form-label">Department</label>
        <select class="form-select" id="departmentId" name="departmentId">
            <option value="">All Departments</option>
            @foreach (var dept in departments)
            {
                <option value="@dept.Id" selected="@(DepartmentId == dept.Id)">@dept.Name</option>
            }
        </select>
    </div>
    <div class="col-md-2 d-flex align-items-end">
        <button type="submit" class="btn btn-primary w-100">Filter</button>
    </div>
</form>

@if (courses.Count == 0)
{
    <div class="alert alert-info">No courses match your search criteria.</div>
}
else
{
    <table class="table table-striped">
        <thead>
            <tr>
                <th>Course</th>
                <th>Title</th>
                <th>Credits</th>
                <th>Schedule</th>
                <th>Instructor</th>
                <th></th>
            </tr>
        </thead>
        <tbody>
            @foreach (var course in courses)
            {
                <tr>
                    <td>@course.CourseNumber</td>
                    <td>@course.Title</td>
                    <td>@course.Credits</td>
                    <td>@course.Schedule</td>
                    <td>@course.InstructorName</td>
                    <td><a href="courses/@course.Id" class="btn btn-sm btn-outline-secondary">Details</a></td>
                </tr>
            }
        </tbody>
    </table>
}

@code {
    [SupplyParameterFromQuery] public string? Search { get; set; }
    [SupplyParameterFromQuery] public int? DepartmentId { get; set; }

    private List<UniversityCourseCatalog.Models.Course> courses = [];
    private List<UniversityCourseCatalog.Models.Department> departments = [];

    protected override void OnInitialized()
    {
        departments = CatalogService.GetDepartments();
        courses = CatalogService.SearchCourses(Search, DepartmentId);
    }
}

@page "/enroll"
@inject UniversityCourseCatalog.Services.CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Submit Enrollment Request</h1>
<p>Fill out the form below to request enrollment in a course.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4>Enrollment Request Submitted</h4>
        <p>Thank you, <strong>@Model.StudentName</strong>. Your enrollment request for
           <strong>@selectedCourseTitle</strong> has been received.</p>
        <a href="courses" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    if (validationError is not null)
    {
        <div class="alert alert-danger">@validationError</div>
    }

    <form method="post" class="col-md-8">
        <AntiforgeryToken />

        <div class="mb-3">
            <label for="studentName" class="form-label">Full Name</label>
            <input type="text" class="form-control" id="studentName" name="Model.StudentName"
                   value="@Model.StudentName" required />
        </div>

        <div class="mb-3">
            <label for="studentId" class="form-label">Student ID</label>
            <input type="text" class="form-control" id="studentId" name="Model.StudentId"
                   value="@Model.StudentId" required />
        </div>

        <div class="mb-3">
            <label for="courseId" class="form-label">Course</label>
            <select class="form-select" id="courseId" name="Model.CourseId" required>
                <option value="">— Select a course —</option>
                @foreach (var course in courses)
                {
                    <option value="@course.Id" selected="@(Model.CourseId == course.Id)">
                        @course.CourseNumber — @course.Title
                    </option>
                }
            </select>
        </div>

        <button type="submit" class="btn btn-success">Submit Enrollment Request</button>
    </form>
}

@code {
    [SupplyParameterFromForm] public UniversityCourseCatalog.Models.EnrollmentRequest Model { get; set; } = new();
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    private List<UniversityCourseCatalog.Models.Course> courses = [];
    private bool submitted;
    private string? validationError;
    private string? selectedCourseTitle;

    protected override void OnInitialized()
    {
        courses = CatalogService.SearchCourses(null, null);

        if (CourseId.HasValue && Model.CourseId == 0)
        {
            Model.CourseId = CourseId.Value;
        }

        if (HttpMethods.IsPost(HttpContextAccessor.HttpContext?.Request.Method ?? "GET"))
        {
            HandleSubmit();
        }
    }

    [CascadingParameter] public HttpContext? HttpContextAccessor { get; set; }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(Model.StudentName) ||
            string.IsNullOrWhiteSpace(Model.StudentId) ||
            Model.CourseId <= 0)
        {
            validationError = "Please fill in all fields.";
            return;
        }

        var success = CatalogService.SubmitEnrollmentRequest(Model);
        if (success)
        {
            selectedCourseTitle = courses.FirstOrDefault(c => c.Id == Model.CourseId)?.Title ?? "Unknown";
            submitted = true;
        }
        else
        {
            validationError = "Invalid enrollment request. Please verify your information and try again.";
        }
    }
}

